using Microsoft.Extensions.Logging;

namespace MinuteOS.Cli.Build.Steps;

/// <summary>
/// Compiles every source (plus any generated by earlier steps) into objects,
/// reading all toolchain flags from the <see cref="Settings"/> bag. Honors the
/// precompiled header. Reads the <c>Sources</c> slot, writes the <c>Objects</c>
/// slot. This is a built-in pipeline step, not registered for YAML reference; a
/// target swaps it out by listing a different compile step in its pipeline.
/// </summary>
public class GccCompileStep : IBuildStep
{
    public string Name => "gcc:compile";
    public BuildPhase DefaultPhase => BuildPhase.PreLink;

    public async Task<StepResult> ExecuteAsync(StepContext context, CancellationToken cancellationToken)
    {
        var config = context.Configuration;
        var toolchain = context.Toolchain;
        var logger = context.Logger;
        void Info(string m, params object[] a) { if (!context.Quiet) logger.LogInformation(m, a); }

        // Sources slot: discovered sources + anything earlier steps generated.
        var sources = new List<SourceFile>(config.Sources);
        sources.AddRange(context.State.GeneratedSources);
        if (sources.Count == 0)
            return StepResult.Fail("No source files found.");

        // === Precompiled header ===
        if (config.Pch != null)
        {
            Directory.CreateDirectory(config.ObjectDir);
            if (Incremental.NeedsRebuild(config.Pch, config.PchGchFile))
            {
                Info("  precompiling {Pch}", Path.GetFileName(config.Pch));
                var pchArgs = new List<string> { "-c", config.Pch };
                GccFlags.AppendCompileFlags(pchArgs, context, Path.GetDirectoryName(config.Pch)!, SourceLanguage.Cpp);
                pchArgs.AddRange(["-o", config.PchGchFile]);

                var pchResult = await toolchain.RunToolAsync(
                    toolchain.CXX, pchArgs, config.Layout.ProjectRoot, cancellationToken);
                if (!string.IsNullOrWhiteSpace(pchResult.StdErr))
                    logger.LogWarning("{StdErr}", pchResult.StdErr.TrimEnd());
                if (!pchResult.Success)
                    return StepResult.Fail($"Failed to compile precompiled header: exit code {pchResult.ExitCode}");
            }
        }

        Info("Compiling {Count} files...", sources.Count);

        var semaphore = new SemaphoreSlim(context.Parallelism);
        var errors = new List<string>();
        var objects = new List<string>();

        var tasks = sources.Select(async source =>
        {
            var objPath = config.GetObjectPath(source);
            lock (objects) objects.Add(objPath);

            await semaphore.WaitAsync(cancellationToken);
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(objPath)!);

                if (!Incremental.NeedsRebuild(source.FullPath, objPath))
                {
                    logger.LogDebug("Skipping (up-to-date): {Source}", source.RelativePath);
                    return;
                }

                Info("  {Compiler} -c {Source}",
                    source.Language == SourceLanguage.C ? "gcc" : "g++", source.RelativePath);

                var result = await CompileAsync(source, objPath, context, cancellationToken);
                if (!string.IsNullOrWhiteSpace(result.StdErr))
                    logger.LogWarning("{StdErr}", result.StdErr.TrimEnd());
                if (!result.Success)
                    lock (errors) errors.Add($"Failed to compile {source.RelativePath}: exit code {result.ExitCode}");
            }
            finally
            {
                semaphore.Release();
            }
        });

        await Task.WhenAll(tasks);

        if (errors.Count > 0)
        {
            foreach (var error in errors)
                logger.LogError("{Error}", error);
            return StepResult.Fail("Compilation failed");
        }

        // Publish to the Objects slot; the link step orders them deterministically.
        context.State.Objects.AddRange(objects);
        return StepResult.Ok();
    }

    private static async Task<CompilationResult> CompileAsync(
        SourceFile source, string objectPath, StepContext context, CancellationToken cancellationToken)
    {
        var config = context.Configuration;
        var toolchain = context.Toolchain;
        var compiler = source.Language == SourceLanguage.C ? toolchain.CC : toolchain.CXX;

        var args = new List<string> { "-c", source.FullPath };
        GccFlags.AppendCompileFlags(args, context, Path.GetDirectoryName(source.FullPath)!, source.Language);

        // Use the precompiled header for C++ sources, unless this file opts out by
        // being named *.nopch.cpp (mirrors the Make-based build).
        if (source.Language == SourceLanguage.Cpp && config.Pch != null &&
            !source.FullPath.EndsWith(".nopch.cpp", StringComparison.Ordinal))
        {
            args.AddRange(["-include", config.PchIncludeBase, "-Winvalid-pch"]);
        }

        args.AddRange(["-o", objectPath]);
        return await toolchain.RunToolAsync(compiler, args, config.Layout.ProjectRoot, cancellationToken);
    }

}
